<body>
  <div class="todo-container">
    <h1>Todos</h1>

    <div class="input-group">
      <input type="text" id="new-todo" placeholder="What needs to be done?" />
      <button id="add-todo">Add</button>
    </div>

    <div class="filters">
      <button class="filter-btn active" data-filter="all">All</button>
      <button class="filter-btn" data-filter="active">Active</button>
      <button class="filter-btn" data-filter="completed">Completed</button>
    </div>

    <div class="todo-list" id="todo-list">
      <!-- Todos will be rendered here -->
    </div>
  </div>

  <script>
    // Initialize from localStorage or empty array
    let todos = JSON.parse(localStorage.getItem('todos') || '[]');
    let currentFilter = 'all';

    // DOM elements
    const todoList = document.getElementById('todo-list');
    const newTodoInput = document.getElementById('new-todo');
    const addTodoBtn = document.getElementById('add-todo');
    const filterBtns = document.querySelectorAll('.filter-btn');

    // Render todos
    function renderTodos() {
      todoList.innerHTML = '';

      const filteredTodos = filterTodos(todos);

      if (filteredTodos.length === 0) {
        todoList.innerHTML = `
          <div class="empty-state">
            No todos yet. Add one above!
          </div>
        `;
        return;
      }

      filteredTodos.forEach((todo, index) => {
        const todoElement = document.createElement('div');
        todoElement.className = `todo-item${todo.completed ? ' completed' : ''}`;
        todoElement.innerHTML = `
          <button class="toggle-btn" data-index="${index}" aria-pressed="${todo.completed}" title="Toggle completion">
            <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
              <path d="M13 4h-2v2h2v2h2v-2h2v2h-2v2h-2v-2H13v-2zm-6 8h2v2H7v-2zm8-8v2h2V7h-2zm-6 8h2v2H7v-2zm8-8v2h2V7h-2z"/>
            </svg>
          </button>
          <span class="todo-text">${escapeHtml(todo.text)}</span>
          <button class="delete-btn" data-index="${index}" aria-label="Delete todo">×</button>
        `;
        todoList.appendChild(todoElement);
      });

      updateStats();
    }

    // Filter todos
    function filterTodos(todos) {
      switch (currentFilter) {
        case 'active':
          return todos.filter(todo => !todo.completed);
        case 'completed':
          return todos.filter(todo => todo.completed);
        default:
          return todos;
      }
    }

    // Update stats
    function updateStats() {
      const activeCount = todos.filter(t => !t.completed).length;
      const completedCount = todos.filter(t => t.completed).length;

      const statsDiv = document.querySelector('.stats');
      if (statsDiv) {
        statsDiv.innerHTML = `
          <span>${activeCount} active</span>
          ${completedCount > 0 ? `<span>${completedCount} completed</span>` : ''}
        `;
      }
    }

    // Add todo
    function addTodo(text) {
      const trimmedText = text.trim();
      if (!trimmedText) return;

      todos.push({
        id: Date.now(),
        text: trimmedText,
        completed: false
      });

      saveTodos();
      renderTodos();
      newTodoInput.value = '';
    }

    // Toggle todo completion
    function toggleTodo(index) {
      todos[index].completed = !todos[index].completed;
      saveTodos();
      renderTodos();
    }

    // Delete todo
    function deleteTodo(index) {
      todos.splice(index, 1);
      saveTodos();
      renderTodos();
    }

    // Save todos to localStorage
    function saveTodos() {
      localStorage.setItem('todos', JSON.stringify(todos));
    }

    // Escape HTML
    function escapeHtml(text) {
      const div = document.createElement('div');
      div.textContent = text;
      return div.innerHTML;
    }

    // Event listeners
    addTodoBtn.addEventListener('click', () => {
      addTodo(newTodoInput.value);
    });

    newTodoInput.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        addTodo(newTodoInput.value);
      }
    });

    todoList.addEventListener('click', (e) => {
      const index = e.target.dataset.index;

      if (e.target.classList.contains('toggle-btn')) {
        toggleTodo(parseInt(index));
      } else if (e.target.classList.contains('delete-btn')) {
        deleteTodo(parseInt(index));
      }
    });

    filterBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        filterBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        currentFilter = btn.dataset.filter;
        renderTodos();
      });
    });

    // Initial render
    renderTodos();
  </script>
</body>
</html>"}
